import csv
from io import StringIO


def decode_grid(text: str) -> list[tuple[str, ...]]:
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not text.strip():
        return []

    rows = []
    try:
        reader = csv.reader(StringIO(text), delimiter=";", strict=True)
        for raw in reader:
            if all(field.strip() == "" for field in raw):
                continue
            rows.append(tuple(raw))
            expected = len(rows[-1])
            if len(raw) != expected:
                raise ValueError("inconsistent column count")
    except csv.Error as exc:
        raise ValueError("malformed delimited text") from exc
    return rows
```

