import unittest

from solution import decode_grid


class DecodeGridTests(unittest.TestCase):
    def test_basic_semicolon_grid_returns_tuples(self):
        self.assertEqual(
            decode_grid("a;b\nc;d"),
            [("a", "b"), ("c", "d")],
        )

    def test_csv_quoting_and_exact_contents(self):
        text = '"a;b";" spaced ";"say ""hi""";\n"";x;"";'
        self.assertEqual(decode_grid(text), [
            ("a;b", " spaced ", 'say "hi"', ""),
            ("", "x", "", ""),
        ])

    def test_ignores_only_all_whitespace_rows(self):
        text = "   ;\t\nleft; right \n ;value"
        self.assertEqual(
            decode_grid(text),
            [("left", " right "), (" ", "value")],
        )

    def test_first_retained_row_sets_column_count(self):
        self.assertEqual(
            decode_grid(" ; \na;b\n  ;\t\nc;d"),
            [("a", "b"), ("c", "d")],
        )
        with self.assertRaises(ValueError):
            decode_grid("a;b\nc;d;e")
        with self.assertRaises(ValueError):
            decode_grid("a;b;c\nd;e")

    def test_empty_inputs(self):
        self.assertEqual(decode_grid(""), [])
        self.assertEqual(decode_grid(" \t\n "), [])
        self.assertEqual(decode_grid(" ; \n\t;  "), [])

    def test_malformed_quoting(self):
        for text in ('"unterminated;x', '"ok"junk;x'):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    decode_grid(text)

    def test_non_string(self):
        for value in (None, 1, ["a;b"]):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    decode_grid(value)


if __name__ == "__main__":
    unittest.main()

